AcceptOffers = {
    init: async function (app, container ) {
        app = app || session.app;
        container = container || $(".component[name=AcceptOffers]");

        $("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });
        $(".k-state-active", container).removeClass("k-state-active");

        if(getQueryParameter("tab") === "acceptedOffers") { 
            $("[name=acceptedOffers]").addClass("k-state-active");
        } else if(getQueryParameter("tab") === "rejectedOffers") { 
            $("[name=rejectedOffers]").addClass("k-state-active");
        } else {
            $("[name=proposedOffers]").addClass("k-state-active");
        }
    }
}
